"THE JOURNEY":"旅",
"From the Earth in your hands to Planet Javeda, in the little orange ship. Every planet on the way is under a meteor shower.":"手の中の地球から惑星Javedaへ、小さなオレンジの宇宙船で。途中の惑星はどれも流星群に襲われている。",
"The long way home: the meteors hunt you in flight too, and you start with # hearts.":"長い帰り道：飛行中も流星に狙われて、ハートは#つからスタート。",
"PETAL RAIN":"花びらの雨",
"The rose in the canyon is losing its petals. Catch them in the saucer's green beam before they hit the cracked ground.":"峡谷のバラが花びらを散らしてる。ひび割れた地面に落ちる前に、UFOの緑のビームでキャッチしよう。",
"ROSE # / #":"バラ # / #",
