"NIGHT FLIGHT":"ナイトフライト",
"District #, the night the monsters of forgetting came. Fly Jo's saucer between the neon towers and light them up.":"第#地区、忘却のモンスターが来た夜。ネオンのタワーの間でJoのUFOを飛ばして、タワーに明かりを灯そう。",
"# DOWN":"#体撃破",
"STORM #s":"嵐 #秒",
"THE SWARM!":"大群だ！",
"LAZY JO × ZIRKA · LEVEL # PART #":"LAZY JO × ZIRKA · レベル# パート#",
"Zirka's bike over the rooftops of District # - jump the gaps on the beat, and Zirka's gun takes care of what dives in.":"第#地区の屋上をZirkaのバイクで駆け抜けろ - ビートに合わせてすき間をジャンプ。飛び込んでくる敵はZirkaの銃におまかせ。",
"# BOLTS · # DOWN":"稲妻# · #体撃破",
"x# · # BOLTS · # DOWN":"x# · 稲妻# · #体撃破",
"The King of Forgetting hangs over the city. Bring him down before the song ends. Gadgets float up for Jo - and the wolf token hands the fight to Zirka on the roof below.":"忘却の王が街の上空に浮かんでる。曲が終わる前に倒そう。Joのためにガジェットが浮かんでくる - ウルフトークンを取ると、下の屋上にいるZirkaにバトンタッチ。",
"x# · # CORE HITS":"x# · コアヒット#",
"# CORE HITS":"コアヒット#",
"Jo's orange saucer drops into the city from the sky. Freefall down between the towers - through the skybridges, past the cranes and the helicopters - all the way to the streets.":"JoのオレンジのUFOが空から街へ降下。タワーの間を自由落下しよう - 空中通路をくぐり、クレーンやヘリをかわして、地上の通りまで。",
"# M DOWN":"#m降下",
"A CRANE!":"クレーンだ！",
"A night race through the city, towards the moon, in Jo's silver car - its tail lights drawing a trail of light behind it. Seven cars start ahead of you: drift round the corners, hit the nitro on the beat and be first to the river.":"Joのシルバーの車で、月に向かって夜の街を駆け抜けるレース。テールランプが光の軌跡を描く。7台が先にスタート：コーナーはドリフト、ビートに合わせてニトロ、川まで一番乗りを目指そう。",
"P# · # KM/H":"#位 · #km/h",
"Across the hologram clockwork on the stage. Jo's saucer hooks its beam onto the pendulums - swing, let go, fly, hook the next one. Make it all the way before the song runs out.":"ステージのホログラムの時計仕掛けを渡っていこう。JoのUFOがビームで振り子に引っかかる - スイングして、離して、飛んで、次に引っかける。曲が終わる前にゴールまで行こう。",
"# M · # ON THE BEAT":"#m · ビートに合わせて#回",
"YOU FELL":"落ちた",
"The room from the cover, from above. Jo's saucer never stops - it draws a trail of light on the rug wherever it goes. Make it the longest light in the room.":"ジャケットの部屋を上から。JoのUFOは止まらない - どこへ行ってもラグに光の軌跡を描く。部屋で一番長い光にしよう。",
"TRAIL # M":"軌跡 #m",
"CROSSED!":"交差した！",
"Inside the neon cup from the cover. The saucer is the paddle, a purple drop is the ball - smash the ice cubes and the pink splash before the ice comes down to you.":"ジャケットのネオンのカップの中。UFOがパドル、紫のしずくがボール - 氷が降りてくる前に、氷とピンクのしぶきを壊そう。",
