"THE ICE COMES DOWN":"氷が降りてきた",
"MISSED IT":"取り逃した",
"The old houses on the street from the cover, at dusk, in the fog. Ghosts come up in the windows on the beat - catch them with the saucer's beam before they duck away.":"ジャケットの通りに並ぶ古い家、夕暮れの霧の中。ビートに合わせて窓に幽霊が現れる - 隠れる前にUFOのビームで捕まえよう。",
