"A purple and gold court floating in the white sky from the cover, Zirka's saucer up by the hoop. Hold to wind up, let go in the green - on the beat it's a swish.":"ジャケットの白い空に浮かぶ紫と金のコート。ZirkaのUFOがゴールのそばに。長押しでためて、緑で離そう - ビートに合わせればスウィッシュ。",
