"The blue sky and the islands from the cover. A gold frame stands in the sea; Jo's saucer carries the pieces down in its beam - island chunks, gold, sky, cloud. Fill a row and it bursts gold.":"ジャケットの青い空と島々。海に金のフレームが立ってる。JoのUFOがビームでピースを運んでくる - 島のかけら、金、空、雲。1列そろうと金色にはじける。",
