"A car park on the wet street from the cover, at night, in the rain. The blue car is boxed in - slide the others out of its way so it can drive out.":"ジャケットの濡れた通りにある駐車場、雨の夜。青い車が閉じ込められてる - ほかの車をスライドしてどかして、外に出してあげよう。",
