"A purple and gold court floating in the white sky from the cover, Zirka's saucer up by the hoop. Hold to wind up, let go in the green - on the beat it's a swish. <b>Endless:</b> the shots never stop - harder every # bars, a heart back every #.":"ジャケットの白い空に浮かぶ紫と金のコート、リングのそばにはZirkaのUFO。長押しでタメて、緑で離そう - ビートに合わせればスウィッシュ。<b>エンドレス：</b>シュートは終わらない - #小節ごとに難しくなり、#小節ごとにハート1つ回復。",
