"The city at sunset from the cover, high over the towers - the sky going from purple to fire, the towers lit. <b>Part # · Rooftop Golf:</b> nine holes on the roofs, every one with something new. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"ジャケットの夕暮れの街、ビルのはるか上空 - 紫から炎の色に変わる空、灯るビル。<b>パート# · Rooftop Golf：</b>屋上に9ホール、どれも新しい仕掛けつき。<b>エンドレス：</b>終わらない - #小節ごとに難しくなり、#小節ごとにハートが1つ戻る。",
"The city at sunset from the cover, high over the towers - the sky going from purple to fire, the towers lit. <b>Part # · Sky Hockey:</b> air hockey on a roof against the shadow, round after round. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"ジャケットの夕暮れの街、ビルのはるか上空 - 紫から炎の色に変わる空、灯るビル。<b>パート# · Sky Hockey：</b>屋上で影とエアホッケー、ラウンドを重ねていく。<b>エンドレス：</b>終わらない - #小節ごとに難しくなり、#小節ごとにハートが1つ戻る。",
"The night from the cover - the stars, the lasers crossing over the black car with the glowing pink hood and the rider on its roof - and Jo's saucer. <b>Part # · Neon Pinball:</b> a real pinball table on the floor in front of the car. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"ジャケットの夜 - 星、ピンクに光るボンネットの黒い車と屋根の上のライダー、その上を交差するレーザー - そしてJoのUFO。<b>パート# · Neon Pinball：</b>車の前の床に本物のピンボール台。<b>エンドレス：</b>終わらない - #小節ごとに難しくなり、#小節ごとにハートが1つ戻る。",
"The night from the cover - the stars, the lasers crossing over the black car with the glowing pink hood and the rider on its roof - and Jo's saucer. <b>Part # · Speaker Push:</b> the dance floor, the speakers off, the pads where they belong. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"ジャケットの夜 - 星、ピンクに光るボンネットの黒い車と屋根の上のライダー、その上を交差するレーザー - そしてJoのUFO。<b>パート# · Speaker Push：</b>ダンスフロア、止まったスピーカー、それぞれの置き場所を示すパッド。<b>エンドレス：</b>終わらない - #小節ごとに難しくなり、#小節ごとにハートが1つ戻る。",
"The wet street from the cover at night, in the rain. The saucer's beam goes flat across it - bend it with the mirrors so it reaches the car's headlights. <b>Endless:</b> it never stops - the clock gets shorter every # bars, a heart back every #.":"ジャケットの濡れた夜の通り、雨の中。UFOのビームがまっすぐ横切る - 鏡で曲げて車のヘッドライトまで届けよう。<b>エンドレス：</b>終わらない - #小節ごとに制限時間が短くなり、#小節ごとにハートが1つ戻る。",
"A car park on the wet street from the cover, at night, in the rain. The blue car is boxed in - slide the others out of its way so it can drive out. <b>Endless:</b> it never stops - the clock gets shorter every # bars, a heart back every #.":"ジャケットの濡れた通りにある駐車場、雨の夜。青い車が閉じ込められた - 他の車をずらして道を空け、出られるようにしよう。<b>エンドレス：</b>終わらない - #小節ごとに制限時間が短くなり、#小節ごとにハートが1つ戻る。",
"The crowd from the cover under the blue light, every hand up, the big white light behind - and nine lights over them, each its own note. Jo's saucer hovers by the one you play. <b>Endless:</b> the pattern never stops - less time every # bars, a heart back every #.":"ジャケットの青いライトの下の観客、全員が手を上げ、背後には大きな白い光 - その上に9つのライト、それぞれが自分の音を鳴らす。JoのUFOは君が鳴らしたライトのそばに浮かぶ。<b>エンドレス：</b>パターンは終わらない - #小節ごとに時間が減り、#小節ごとにハートが1つ戻る。",
"Across the hologram clockwork on the stage. Jo's saucer hooks its beam onto the pendulums - swing, let go, fly, hook the next one. Make it all the way before the song runs out. <b>Endless:</b> the clockwork never ends - wider every # bars, a heart back every #.":"ステージのホログラムの時計仕掛けを渡っていく。JoのUFOがビームで振り子をつかむ - 揺れて、離して、飛んで、次をつかむ。曲が終わる前に渡りきろう。<b>エンドレス：</b>時計仕掛けは終わらない - #小節ごとに間隔が広がり、#小節ごとにハートが1つ戻る。",
"The room from the cover, from above. Jo's saucer never stops - it draws a trail of light on the rug wherever it goes. Make it the longest light in the room. <b>Endless:</b> it never ends - faster every # bars, a heart back every #.":"上から見たジャケットの部屋。JoのUFOは止まらない - 進んだところすべて、ラグの上に光の軌跡を描く。部屋で一番長い光にしよう。<b>エンドレス：</b>終わらない - #小節ごとに速くなり、#小節ごとにハートが1つ戻る。",
