"Score <b>#</b> · # m · # pendulums · # sparks · # on the beat":"スコア <b>#</b> · #m · 振り子# · スパーク# · ビートに合わせて#",
"<b>#</b> of swinging · # m · # pendulums · # sparks · # on the beat":"スイングで<b>#</b> · #m · 振り子# · スパーク# · ビートに合わせて#",
