"The heart keeps breaking. Mend it, and its pieces scatter again. Every piece has a <b>clock</b>, and each round the ghosts are faster and there are more of them. <b># hearts</b>: a ghost or a late piece takes one, one comes back every # bars.":"ハートは何度も壊れる。直しても、かけらはまた散らばる。かけらには<b>制限時間</b>があって、ラウンドごとにゴーストは速く、数も増えていく。<b>ハート#個</b>：ゴーストに触れるか、かけらが間に合わないと1つ減り、#小節ごとに1つ戻る。",
"The heart keeps breaking. Mend it, and its pieces scatter again in the thick fog. Every piece has a <b>clock</b>, and each round the ghosts are faster and there are more of them. <b># hearts</b>: a ghost or a late piece takes one, one comes back every # bars.":"ハートは何度も壊れる。直しても、かけらは濃い霧の中にまた散らばる。かけらには<b>制限時間</b>があって、ラウンドごとにゴーストは速く、数も増えていく。<b>ハート#個</b>：ゴーストに触れるか、かけらが間に合わないと1つ減り、#小節ごとに1つ戻る。",
"The heart keeps breaking. Mend it, and its pieces scatter again, glowing only on the heartbeat. Every piece has a <b>clock</b>, and each round the ghosts are faster and there are more of them. <b># hearts</b>: a ghost or a late piece takes one, one comes back every # bars.":"ハートは何度も壊れる。直しても、かけらは鼓動のときだけ光りながら、また散らばる。かけらには<b>制限時間</b>があって、ラウンドごとにゴーストは速く、数も増えていく。<b>ハート#個</b>：ゴーストに触れるか、かけらが間に合わないと1つ減り、#小節ごとに1つ戻る。",
