"Every knot undone.<br>Part #, <b>Bird Code</b>, is open.":"結び目は全部ほどけた。<br>パート#「<b>Bird Code</b>」が解放！",
"Every code cracked.<br>Level # cleared: <b>Untangle ∞</b>, <b>Bird Code ∞</b> and the <b>Remix ∞</b> are open in the gold Endless list.":"暗号は全部解いた。<br>レベル#クリア：<b>Untangle ∞</b>、<b>Bird Code ∞</b>、<b>リミックス ∞</b>がゴールドのエンドレスリストで解放！",
"Drag the birds until no strings cross - the red strings are the ones crossing, a red X shows where. <b>Go again.</b>":"糸が交差しなくなるまで鳥をドラッグ - 交差してるのは赤い糸で、赤いXが交差点だよ。<b>もう一回。</b>",
"Tap birds at the front to fill the wire. Gold bead: right bird, right spot. Blue bead: right bird, wrong spot. <b>Go again.</b>":"手前の鳥をタップして電線を埋めよう。金の玉：鳥も位置も正解。青の玉：鳥は正解、位置がちがう。<b>もう一回。</b>",
"Gold bead: right bird, right spot. Blue bead: right bird, wrong spot. No bead: that bird isn't hiding. <b>Go again.</b>":"金の玉：鳥も位置も正解。青の玉：鳥は正解、位置がちがう。玉なし：その鳥は隠れてない。<b>もう一回。</b>",
"A PAIR ON THE BEAT<small>+#</small>":"ビートでペア！<small>+#</small>",
"A PAIR<small>+#</small>":"ペア！<small>+#</small>",
"BED CLEARED<small>+# · a bigger one</small>":"ベッドクリア<small>+# · 次はもっと大きい</small>",
"SNAP!<small>+# · both piles</small>":"SNAP!<small>+# · 両方の山ゲット</small>",
"SNAP! ON THE BEAT<small>+# · both piles</small>":"ビートでSNAP!<small>+# · 両方の山ゲット</small>",
"The two rooms from the cover, split on the diagonal - hers pink, his purple; her reading with the long red hair, him on his phone in the headphones - and Jo's saucer. <b>Part # · Love Cards:</b> the cards face down on her bed. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"ジャケットの2つの部屋、斜めに分かれてる - 彼女の部屋はピンク、彼のは紫。長い赤髪で本を読む彼女、ヘッドホンでスマホをいじる彼 - そしてJoのUFO。<b>パート# · Love Cards：</b>彼女のベッドに伏せられたカード。<b>エンドレス：</b>終わりなし - #小節ごとに難しくなり、#小節ごとにハートが1つ戻る。",
"The two rooms from the cover, split on the diagonal - hers pink, his purple; her reading with the long red hair, him on his phone in the headphones - and Jo's saucer. <b>Part # · Snap:</b> her pile and his on the floor between them. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"ジャケットの2つの部屋、斜めに分かれてる - 彼女の部屋はピンク、彼のは紫。長い赤髪で本を読む彼女、ヘッドホンでスマホをいじる彼 - そしてJoのUFO。<b>パート# · Snap：</b>2人の間の床に置かれた彼女の山と彼の山。<b>エンドレス：</b>終わりなし - #小節ごとに難しくなり、#小節ごとにハートが1つ戻る。",
"Score <b>#</b> · # pairs · # beds cleared":"スコア <b>#</b> · ペア#組 · ベッドクリア#回",
"Score <b>#</b> · # pairs · # beds cleared · # on the beat":"スコア <b>#</b> · ペア#組 · ベッドクリア#回 · ビートに合わせて#回",
"<b>#</b> in their rooms · # pairs · # beds cleared":"2人の部屋で<b>#</b> · ペア#組 · ベッドクリア#回",
"<b>#</b> in their rooms · # pairs · # beds cleared · # on the beat":"2人の部屋で<b>#</b> · ペア#組 · ベッドクリア#回 · ビートに合わせて#回",
"Score <b>#</b> · # snaps of # cards":"スコア <b>#</b> · SNAP#回（カード#枚中）",
"<b>#</b> in their rooms · # snaps of # cards":"2人の部屋で<b>#</b> · SNAP#回（カード#枚中）",
"Every pair found.<br>Part #, <b>Snap</b>, is open.":"ペアは全部見つけた。<br>パート#「<b>Snap</b>」が解放！",
"Snap. Blind love.<br>Level # cleared: <b>Love Cards ∞</b>, <b>Snap ∞</b> and the <b>Remix ∞</b> are open in the gold Endless list.":"Snap。恋は盲目。<br>レベル#クリア：<b>Love Cards ∞</b>、<b>Snap ∞</b>、<b>リミックス ∞</b>がゴールドのエンドレスリストで解放！",
"Turn two cards: the same picture is a pair. Remember where the others were - and clear the bed before the time's up. <b>Go again.</b>":"カードを2枚めくろう：同じ絵ならペア。他のカードの場所を覚えて - 時間切れまでにベッドをクリア。<b>もう一回。</b>",
"When both piles show the same picture, tap - SNAP. A heart and a broken heart aren't the same. <b>Go again.</b>":"両方の山に同じ絵が出たらタップ - SNAP。ハートと割れたハートは別物だよ。<b>もう一回。</b>",
"Only snap when both piles show the same picture. A heart and a broken heart aren't the same, nor the sun and the moon. <b>Go again.</b>":"両方の山が同じ絵のときだけSNAPしよう。ハートと割れたハートは別物、太陽と月もね。<b>もう一回。</b>",
"PAD MEMORY<small>watch the pads - then play them back</small>":"PAD MEMORY<small>パッドを見て - 同じように叩こう</small>",
"WATCH<small>watch the pads light up</small>":"よく見て<small>光るパッドを見よう</small>",
"NICE<small>+# · one more pad</small>":"ナイス<small>+# · パッドが1つ増える</small>",
"# IN A ROW<small>+# · one more pad</small>":"#連続<small>+# · パッドが1つ増える</small>",
"FULL PATTERN<small>+# · a fresh one</small>":"パターン完成<small>+# · 新しいパターン</small>",
"WATCH · QUICK<small>double points</small>":"よく見て · 速いよ<small>ポイント2倍</small>",
"Jo's studio at night from the cover - the big speakers, the screen with the crowd, the skull on the desk. On the desk the drum machine: # pads lit from under, each its own note, and Jo's saucer hovering over them. <b>Endless:</b> the patterns never stop - less time every # bars, a heart back every #.":"ジャケットに描かれた夜のJoのスタジオ - 大きなスピーカー、観客が映るスクリーン、デスクのドクロ。デスクの上にはドラムマシン：下から光る#個のパッド、それぞれ違う音、その上に浮かぶJoのUFO。<b>エンドレス：</b>パターンは終わらない - #小節ごとに時間が短くなり、#小節ごとにハートが1つ戻る。",
"Up all night and it's all still there.<br>Level # cleared: <b>Pad Memory ∞</b> is open in the gold Endless list.":"一晩中起きてても、全部まだそこにある。<br>レベル#クリア：<b>Pad Memory ∞</b>がゴールドのエンドレスリストで解放！",
"Play the pattern back before the time runs out - one pad a beat is plenty. <b>Go again.</b>":"時間切れまでにパターンを叩き返そう - 1拍に1パッドで十分。<b>もう一回。</b>",
"Watch the order the pads light up in, then play it back the same way - say the colours to yourself. <b>Go again.</b>":"パッドが光る順番を見て、同じ順に叩こう - 色を心の中で唱えるといいよ。<b>もう一回。</b>",
